import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import java.util.*;

public final class StarterDeck100MedichamTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){for(boolean attack:List.of(false,true))opponentHistory(attack);for(boolean bench:List.of(false,true))extra(bench);noKo();protectedTarget();copied();uppercut();deckOut();System.out.println("StarterDeck100MedichamTest passed: counter KO causation, Active/Bench selection, prizes/replacement, extra-turn draw and resets, skipped Checkup, cross-Pokemon history, copy ruling, protection, Resistance and deck-out");}
    static void loop(ServerMatch m,UUID target){m.attack(A,"yoga-loop");StarterDeck100PokemonTest.choosePokemon(m,target);}
    static void extra(boolean bench){var m=StarterDeck100PokemonTest.game(221);StarterDeck100PokemonTest.charge(m,0);var target=bench?m.benchPokemonView(B).getFirst():m.activePokemonView(B);m.placeDamageCountersByEffect(A,B,target.pokemonId(),(target.hitPoints()-20)/10);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);var energy=StarterDeck100PokemonTest.hand(m,"sd100_cn_grass_energy");m.attachEnergy(A,energy.instanceId(),m.activePokemonView(A).pokemonId());int turn=m.turnNumber(),hand=m.privateView(A).hand().size(),deck=m.privateView(A).deck().size();loop(m,target.pokemonId());check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.turnNumber()==turn,"extra turn began before prizes");StarterDeck100CombatTest.settleKnockouts(m);check(m.currentPlayer().equals(A)&&m.turnNumber()==turn+1&&m.privateView(A).deck().size()==deck-1&&m.privateView(A).hand().size()==hand+3,"extra turn failed draw or V prize count");check(m.activePokemonView(A).damage()==0&&m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED),"Checkup was not skipped");var next=StarterDeck100PokemonTest.hand(m,"sd100_cn_grass_energy");m.attachEnergy(A,next.instanceId(),m.activePokemonView(A).pokemonId());var rng=m.randomTranscript();TopDeckLookTest.rejects(()->m.attack(A,"yoga-loop"));check(rng.equals(m.randomTranscript()),"history rejection used RNG");m.switchActiveByEffect(A,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100PokemonTest.charge(m,0);TopDeckLookTest.rejects(()->m.attack(A,"yoga-loop"));m.endTurn(A);m.endTurn(B);m.attack(A,"yoga-loop");StarterDeck100PokemonTest.choosePokemon(m,m.activePokemonView(B).pokemonId());check(m.currentPlayer().equals(B),"unused previous own turn did not clear history");}
    static void opponentHistory(boolean attackDamage){
        var m=StarterDeck100PokemonTest.game(221);m.placeDamageCountersByEffect(A,A,m.activePokemonView(A).pokemonId(),20);
        if(attackDamage)for(int i=0;i<2;i++)StarterDeck100EnergyTest.attach(m,A,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());
        m.endTurn(A);if(attackDamage)m.attack(B,"leaf-drain");else m.knockOutPokemonByEffect(B,A,m.activePokemonView(A).pokemonId());StarterDeck100CombatTest.settleKnockouts(m);if(m.currentPlayer().equals(B))m.endTurn(B);
        check(lastOpponentKo(m,"KNOCKED_OUT_LAST_TURN")&&lastOpponentKo(m,"KNOCKED_OUT_BY_ATTACK_LAST_TURN")==attackDamage,"preceding opponent KO not tracked");
        var target=m.activePokemonView(B);m.placeDamageCountersByEffect(A,B,target.pokemonId(),(target.hitPoints()-target.damage()-20)/10);StarterDeck100PokemonTest.charge(m,0);loop(m,target.pokemonId());StarterDeck100CombatTest.settleKnockouts(m);
        check(m.currentPlayer().equals(A)&&lastOpponentKo(m,"KNOCKED_OUT_LAST_TURN")&&lastOpponentKo(m,"KNOCKED_OUT_BY_ATTACK_LAST_TURN")==attackDamage,"extra own turn forgot last OPPONENT turn KO");
        m.endTurn(A);m.endTurn(B);check(!lastOpponentKo(m,"KNOCKED_OUT_LAST_TURN")&&!lastOpponentKo(m,"KNOCKED_OUT_BY_ATTACK_LAST_TURN"),"new opponent turn did not expire old KO");
    }
    static boolean lastOpponentKo(ServerMatch m,String type){var e=new dev.hua.ptcglive.engine.effect.EffectDefinition("draw",dev.hua.ptcglive.engine.effect.EffectTarget.SELF,Map.of("amount","1"),List.of(new dev.hua.ptcglive.engine.effect.ConditionDefinition(dev.hua.ptcglive.engine.effect.ConditionType.valueOf(type),Map.of(),List.of())),List.of());int before=m.privateView(A).hand().size();m.executeEffectProgramByRule(A,m.activePokemonView(A).pokemonId(),new dev.hua.ptcglive.engine.effect.EffectProgram(List.of(new dev.hua.ptcglive.engine.effect.TriggeredEffects(dev.hua.ptcglive.engine.effect.EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e)))),dev.hua.ptcglive.engine.effect.EffectTrigger.ON_CARD_PLAYED);return m.privateView(A).hand().size()==before+1;}
    static void noKo(){var m=StarterDeck100PokemonTest.game(221);StarterDeck100PokemonTest.charge(m,0);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);loop(m,m.activePokemonView(B).pokemonId());check(m.currentPlayer().equals(B)&&m.activePokemonView(B).damage()==20&&m.activePokemonView(A).damage()==10,"non-KO granted extra turn or damage modifiers applied");m.endTurn(B);TopDeckLookTest.rejects(()->m.attack(A,"yoga-loop"));}
    static void protectedTarget(){var m=StarterDeck100PokemonTest.game(221);StarterDeck100PokemonTest.charge(m,0);var target=m.activePokemonView(B);m.placeDamageCountersByEffect(A,B,target.pokemonId(),(target.hitPoints()-20)/10);m.endTurn(A);StarterDeck100CounterMoveTest.shield(m,B,target.pokemonId(),"ATTACK");m.endTurn(B);loop(m,target.pokemonId());check(m.currentPlayer().equals(B)&&m.activePokemonView(B).damage()==target.hitPoints()-20,"immune target granted extra turn");}
    static void copied(){var selected=StarterDeck100CombatTest.COMBAT.pokemon(StarterDeck100PokemonTest.id(221)).orElseThrow().attacks().getFirst();var m=CopyAttackTest.fixture(selected);CopyAttackTest.pay(m);var a=CopyAttackTest.A;var b=CopyAttackTest.B;for(int i=0;i<1;i++){var target=m.benchPokemonView(b).isEmpty()?m.activePokemonView(b):m.benchPokemonView(b).getFirst();m.placeDamageCountersByEffect(a,b,target.pokemonId(),28);var c=m.copyAttackOptions(a,"copy").getFirst();CopyAttackTest.copy(m,c,List.of(),List.of());var p=m.effectPokemonPrompt(a);m.chooseEffectPokemon(a,p.resolutionId(),p.step(),target.pokemonId());while(m.phase()==MatchPhase.PRIZE_SELECTION)m.takePrizeAt(m.pendingChoicePlayer(),m.clientView(m.pendingChoicePlayer()).prizeSlots().getFirst());if(i==0)check(m.currentPlayer().equals(a),"copied loop failed extra turn");}var again=m.copyAttackOptions(a,"copy").getFirst();var before=m.clientView(a);CopyAttackTest.reject(()->CopyAttackTest.copy(m,again,List.of(),List.of()));check(before.equals(m.clientView(a)),"copied Yoga Loop cooldown bypassed or mutated state");}
    static void uppercut(){var m=StarterDeck100PokemonTest.game(221,171);StarterDeck100PokemonTest.attack(m,1);check(m.lastAttack().finalDamage()==100&&!m.lastAttack().resistanceApplied(),"Smash Uppercut applied Fighting Resistance");}
    static void deckOut(){var m=StarterDeck100PokemonTest.game(221);StarterDeck100PokemonTest.charge(m,0);var target=m.activePokemonView(B);m.placeDamageCountersByEffect(A,B,target.pokemonId(),(target.hitPoints()-20)/10);m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size());loop(m,target.pokemonId());StarterDeck100CombatTest.settleKnockouts(m);check(m.phase()==MatchPhase.FINISHED&&m.result().reason()==MatchResult.Reason.DECK_OUT,"extra-turn empty deck did not lose");}
}
